import base64,hashlib,json,os,pathlib,subprocess,re
t=pathlib.Path(os.environ['RUNNER_TEMP']);b=pathlib.Path('tools/direct_demand/operations')
name=os.environ['LINK_SCOPE_FILENAME'];assert pathlib.Path(name).name==name
scopeRaw=(b/name).read_bytes();assert hashlib.sha256(scopeRaw).hexdigest()==os.environ['EXPECTED_LINK_SCOPE_SHA256'];scope=json.loads(scopeRaw)
pn=os.environ['LINK_EXECUTION_PLAN_FILENAME'];assert pathlib.Path(pn).name==pn
plan=json.loads((b/pn).read_text());assert plan['operation']==scope['update_operation'] and plan['scope_sha256']==os.environ['EXPECTED_LINK_SCOPE_SHA256'] and plan['expected_source']==os.environ['EXPECTED_PRODUCTION_SHA']
ps=list((t/'prepared-links').rglob('update-index.json'));assert len(ps)==1;root=ps[0].parent;index=json.loads(ps[0].read_text());summary=json.loads((root/'prepare-summary.json').read_text())
ids=plan['hotel_ids'];assert 0<len(ids)==len(index)<=10 and [x['hotel_id'] for x in index]==ids==summary['prepared_native_ids'] and set(ids)<=set(scope['native_hotel_ids'])
assert summary['operation']==plan['operation'] and summary['prepared_prices']==0 and summary['quote_state']=='NOQUOTE' and summary['context_run']==plan['context_run'] and summary['scope_sha256']==plan['scope_sha256'] and summary['prepared_source_sha']==plan['frozen_prepared_source'] and summary['context_source_sha']==plan['context_source_sha']
template=(b/'update-priced-hotel-search-links-explicit-noquote-20261105.php').read_bytes();assert hashlib.sha256(template).hexdigest()==summary['template_sha256']==plan['template_sha256']
accepted=json.loads((b/'commercial-hotel-materials-20261105-161-acceptance-state.json').read_text());assert len(accepted['price_hotel_ids'])==scope['expected_priced_count'] and len(accepted['search_link_hotel_ids'])==scope['expected_linked_count'] and set(ids)<=set(accepted['price_hotel_ids']) and not set(ids)&set(accepted['search_link_hotel_ids'])
identities=summary['native_bindings'];frozenSource=plan['frozen_prepared_source'];source=plan['expected_source'];assert re.fullmatch('[a-f0-9]{40}',source) and re.fullmatch('[a-f0-9]{40}',frozenSource)
assert [x['local_tv_id'] for x in identities]==scope['native_hotel_ids'] and len(identities)==len(scope['native_hotel_ids'])
assert source==frozenSource or plan['runtime_source_header_rebind_reviewed_publishing21_unchanged'] is True
intents=[]
for e in index:
 hid=int(e['hotel_id']);op=scope['update_hotel_operation_prefix']+str(hid)+scope['update_hotel_operation_suffix'];assert e['folder']==str(hid) and e['operation']==op and e['quote_state']=='NOQUOTE'
 folder=root/e['folder'];raw=(folder/'update-manifest.json').read_bytes();m=json.loads(raw);a=json.loads((folder/'update-approval.json').read_text());fr=(folder/'context-frame.private.json').read_bytes();f=json.loads(fr);v=f['binding'];fh=hashlib.sha256(fr).hexdigest();r=m['rows'][0]
 assert set(a)=={'schema_version','operation','expected_installed_sha','hotel_ids','manifest_sha256'} and a['schema_version']==1 and a['expected_installed_sha']==frozenSource and a['hotel_ids']==[hid] and a['operation']==m['operation']==op and a['manifest_sha256']==hashlib.sha256(raw).hexdigest()==e['manifest_sha256']
 assert f['capture_run']==plan['context_run'] and f['capture_source_sha']==plan['context_source_sha'] and f['capture_operation']==scope['operation'] and m['quote_state']==v['quote_state']=='NOQUOTE' and m['price_total_verified'] is False and len(m['rows'])==1 and r['hotel_id']==v['native_hotel_id']==hid and r['legacy_context_sha256']==fh and m['update_kind']=='search_link_only'
 assert v['original_role_proof_kind']=='current_confirmed_own_price_manifest_and_receipt' and v['prior_owned_price']['confirmed_own_receipt_and_current_version'] is True and v['prior_owned_price']['operation']==scope['prior_price_operations'][str(hid)] and r['expected_prior_price_metadata']==v['prior_owned_price']['price_metadata'] and all(v['contexts'][z]['prior_price_metadata']==r['expected_prior_price_metadata'] for z in ['max','telegram'])
 assert not any(k in m for k in ['quote_response_sha256','quote_epoch_utc','quote_index','quote_total_amount','quote_currency','quote_origin_operation'])
 values={'EXPECTED_INSTALLED_SHA':frozenSource,'APPROVED_MANIFEST_SHA256':a['manifest_sha256'],'MANIFEST_BASE64':base64.b64encode(raw).decode(),'APPROVED_UPDATE_HOTEL_ID':hid,'APPROVED_UPDATE_KEY_B64':base64.b64encode(v['key'].encode()).decode(),'APPROVED_UPDATE_LOGICAL_B64':base64.b64encode(v['logical_id'].encode()).decode(),'APPROVED_UPDATE_OPERATION':op,'APPROVED_LEGACY_CONTEXT_B64':base64.b64encode(fr).decode(),'APPROVED_LEGACY_CONTEXT_SHA256':fh,'APPROVED_IDENTITY_BINDINGS_B64':base64.b64encode(json.dumps(identities,ensure_ascii=False,separators=(',',':')).encode()).decode(),'APPROVED_SEARCH_URL_B64':base64.b64encode(r['search_link_url'].encode()).decode(),'APPROVED_LINK_CAPTURE_OPERATION':f['capture_operation'],'APPROVED_LINK_CAPTURE_RUN':f['capture_run'],'APPROVED_LINK_CAPTURE_SOURCE':f['capture_source_sha'],'APPROVED_LINK_UPDATE_PREFIX':scope['update_hotel_operation_prefix'],'APPROVED_LINK_UPDATE_SUFFIX':scope['update_hotel_operation_suffix']}
 assert set(re.findall(rb'\bAPPROVED_[A-Z0-9_]+\b',template))<={k.encode() for k in values},'EXECUTION_HEADER_OPERATION_CONSTANTS_UNDECLARED'
 prefix=b"<?php\ndeclare(strict_types=1);\n";assert template.startswith(prefix)
 def script(z):return prefix+b''.join(('const '+k+'='+json.dumps(x,ensure_ascii=False)+';\n').encode() for k,x in z.items())+template[len(prefix):]
 expected=script(values);assert (folder/'update.php').read_bytes()==expected and hashlib.sha256(expected).hexdigest()==e['script_sha256'],'FROZEN_NOQUOTE_LINK_SCRIPT_BYTES_CHANGED'
 values['EXPECTED_INSTALLED_SHA']=source;execution=script(values);(folder/'execution.php').write_bytes(execution)
 ea=dict(a);ea['expected_installed_sha']=source;(folder/'execution-approval.json').write_text(json.dumps(ea)+'\n')
 lint=subprocess.run(['php','-l',str(folder/'execution.php')],capture_output=True);assert lint.returncode==0,'FROZEN_EXECUTION_PHP_SYNTAX_CHANGED'
 intent=json.loads((folder/'update-intent.json').read_text());assert intent['operation']==op and intent['manifest_sha256']==a['manifest_sha256'] and intent['expected_source']==frozenSource and intent['quote_state']=='NOQUOTE' and intent['context_run']==plan['context_run'] and intent['max_content_edits']==2 and intent['new_posts']==intent['gateway_calls']==intent['source_searches']==0
 intent.update(prepared_expected_source=frozenSource,execution_expected_source=source,frozen_script_sha256=hashlib.sha256(expected).hexdigest(),execution_script_sha256=hashlib.sha256(execution).hexdigest());intents.append(intent)
(t/'link-execution-root.txt').write_text(str(root)+'\n');(t/'all-link-execution-intents.private.json').write_text(json.dumps(intents)+'\n')
